import sys, re, os
KEY = re.compile(r'(?m)^\s*(?:private\s+|value\s+|test\s+|abstract\s+|atomic\s+|io\s+|widening\s+|getter\s+|setter\s+)*(trait|object|opr|api|component|end)\b|(?m)^\s*\w[\w\']*\s*(\[\\.*)?\(.*\)\s*:\s*|\bopr\b|\bdef\b')
DECL = re.compile(r'\b(trait|object|opr|component|api)\b')
def blocks(text):
    res=[]; i=0; n=len(text); depth=0; start=None
    while i < n-1:
        if text[i]=='(' and text[i+1]=='*':
            if depth==0: start=i
            depth+=1; i+=2; continue
        if text[i]=='*' and text[i+1]==')' and depth>0:
            depth-=1; i+=2
            if depth==0: res.append((start,i))
            continue
        i+=1
    return res
for f in sys.argv[1:]:
    try: t=open(f,encoding='utf-8',errors='replace').read()
    except: continue
    for (s,e) in blocks(t):
        body=t[s:e]
        ls=t.count('\n',0,s)+1; le=t.count('\n',0,e)+1
        nl=le-ls+1
        if nl < 2: continue
        # heuristic: contains a declaration keyword at line start
        if re.search(r'(?m)^\s*(trait|object|opr|api|component|private|abstract|value)\b', body) or re.search(r'(?m)^\s*\w[\w\']*(\[\\[^\]]*\\\])?\s*\([^)]*\)\s*:\s*\S', body):
            print("%s:%d-%d (%d lines)" % (f, ls, le, nl))
EOF
